/**
 * Returns an SVG `viewBox` string fitting the given polygons (with margin) and
 * the larger of its width and height.
 */ function getViewBox(pss) {
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const ps of pss){
        for (const [x, y] of ps){
            minX = min(minX, x);
            minY = min(minY, y);
            maxX = max(maxX, x);
            maxY = max(maxY, y);
        }
    }
    const m = 0.05 * max(maxX - minX, maxY - minY);
    const w = maxX - minX + 2 * m;
    const h = maxY - minY + 2 * m;
    return {
        viewBox: `${minX - m} ${minY - m} ${w} ${h}`,
        size: max(w, h)
    };
}



